package com.jobportal;

import jakarta.persistence.*;
import java.time.*;
import java.math.BigDecimal;

@Entity @Table(name="users") class UserAccount {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true) String email; @Column(name="password_hash",nullable=false) String passwordHash; @Column(name="full_name",nullable=false) String fullName; boolean enabled=true; @Column(name="created_at") LocalDateTime createdAt=LocalDateTime.now();
 @ManyToMany(fetch=FetchType.EAGER) @JoinTable(name="user_roles",joinColumns=@JoinColumn(name="user_id"),inverseJoinColumns=@JoinColumn(name="role_id")) java.util.Set<Role> roles=new java.util.HashSet<>();
}
@Entity @Table(name="roles") class Role { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(unique=true,nullable=false) String name; protected Role(){} Role(String n){name=n;} }
@Entity @Table(name="seeker_profiles") class SeekerProfile { @Id @Column(name="user_id") Long userId; String headline; @Column(columnDefinition="TEXT") String summary; @Column(columnDefinition="TEXT") String skills; String location; @Column(name="resume_file_name") String resumeFileName; @Column(name="resume_path") String resumePath; }
@Entity @Table(name="companies") class Company { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(name="owner_user_id",nullable=false) Long ownerUserId; @Column(nullable=false) String name; @Column(columnDefinition="TEXT") String description; String website,location; @Column(name="logo_url") String logoUrl; boolean verified; }
@Entity @Table(name="jobs") class Job { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(name="company_id",nullable=false) Long companyId; @Column(nullable=false) String title; @Column(nullable=false,columnDefinition="TEXT") String description; String location; @Column(name="job_type") String jobType; String category; @Column(name="salary_min") BigDecimal salaryMin; @Column(name="salary_max") BigDecimal salaryMax; @Column(name="experience_level") String experienceLevel; String status="DRAFT"; LocalDate deadline; @Column(name="created_at") LocalDateTime createdAt=LocalDateTime.now(); @Column(name="updated_at") LocalDateTime updatedAt=LocalDateTime.now(); }
@Entity @Table(name="applications",uniqueConstraints=@UniqueConstraint(columnNames={"job_id","seeker_id"})) class Application { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(name="job_id") Long jobId; @Column(name="seeker_id") Long seekerId; @Column(name="cover_letter",columnDefinition="TEXT") String coverLetter; @Column(name="resume_path") String resumePath; String status="SUBMITTED"; @Column(name="applied_at") LocalDateTime appliedAt=LocalDateTime.now(); @Column(name="updated_at") LocalDateTime updatedAt=LocalDateTime.now(); }
@Entity @Table(name="saved_jobs") class SavedJob { @EmbeddedId SavedJobId id; @Column(name="created_at") LocalDateTime createdAt=LocalDateTime.now(); }
@Embeddable class SavedJobId implements java.io.Serializable { @Column(name="user_id") Long userId; @Column(name="job_id") Long jobId; public SavedJobId(){} SavedJobId(Long u,Long j){userId=u;jobId=j;} @Override public boolean equals(Object o){return o instanceof SavedJobId x&&java.util.Objects.equals(userId,x.userId)&&java.util.Objects.equals(jobId,x.jobId);} @Override public int hashCode(){return java.util.Objects.hash(userId,jobId);} }
@Entity @Table(name="application_status_history") class ApplicationHistory { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(name="application_id") Long applicationId; @Column(name="changed_by") Long changedBy; @Column(name="old_status") String oldStatus; @Column(name="new_status") String newStatus; @Column(name="changed_at") LocalDateTime changedAt=LocalDateTime.now(); }
